mod action;
mod geometry;
mod index;mod qualify;
#[path="../relation-certificate/verifier.rs"]mod reference;
mod baseline;mod packet;mod verifier;mod sparse;mod cost;
#[path="../source-phases/phase.rs"]mod phase;
use hec_native_ic::{counted,fp::Fp,jac::Curve,poly::Poly,rng::Rng,instance::factor_base};
fn combined(a:&counted::Counts,b:&counted::Counts,c:&counted::Counts)->counted::Counts{let mut out=a.clone();for(p,v)in &mut out{for j in 0..16{v[j]-=b.get(p).map_or(0,|x|x[j]);}}for(p,v)in c{let w=out.entry(*p).or_default();for j in 0..16{w[j]+=v[j];}}out}
fn emit(p:u64,sm:u64,case:usize,rep:usize,name:&str,counts:&counted::Counts){for(m,v)in counts{assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{name}\t{m}\t{}",v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}}
fn main(){counted::disable();geometry::controls();action::controls();let old:Vec<Vec<&str>>=include_str!("../root-pipeline/CONTROL.tsv").lines().skip(1).map(|l|l.split('\t').collect()).collect();let mut calls=0;println!("p\tsm\tcase\trep\tphase\tmodulus\tcounts");for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let curve=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&curve);let base=curve.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=curve.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let target=curve.mul(&d,k);let mut first=None;for rep in 0..2{counted::reset();let r=baseline::solve(&curve,&d,&target,ell,sm,false);let producer=counted::snapshot();counted::disable();assert_eq!(r.k,Some(k));let cert=packet::take();if rep==0{phase::reset();qualify::qualify(&cert);}let external=cost::snapshot();phase::reset();counted::reset();let ok=verifier::verify(&cert);let checking=counted::snapshot();counted::disable();assert!(ok);let phases=phase::snapshot();let mut sum=counted::Counts::new();for((_,m),v)in &phases{let row=sum.entry(*m).or_default();for j in 0..16{row[j]+=v[j];}}assert_eq!(sum,checking);let candidate=combined(&producer,&external,&checking);let oldcost:Vec<Vec<&str>>=include_str!("../certificate-cost/CONTROL.tsv").lines().skip(1).map(|l|l.split('\t').collect()).collect();for (name,counts) in [("producer_with_native_control",&producer),("native_control",&external)]{for(m,v)in counts{let row=oldcost.iter().find(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]==rep.to_string()&&x[4]==name&&x[5]==m.to_string()).unwrap();let expected:Vec<u64>=row[6].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(v.as_slice(),expected.as_slice());}}
 let oldrow=old.iter().find(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]==rep.to_string()&&x[4]=="0"&&x[5]==p.to_string()).unwrap();let original:Vec<u64>=oldrow[12].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(producer[&p].as_slice(),original.as_slice());let signature=(producer.clone(),external.clone(),checking.clone(),candidate.clone(),phases.clone());if let Some(ref prior)=first{assert_eq!(prior,&signature)}else{first=Some(signature)}emit(p,sm,case,rep,"producer_with_native_control",&producer);emit(p,sm,case,rep,"native_control",&external);emit(p,sm,case,rep,"certificate_verifier",&checking);emit(p,sm,case,rep,"derived_candidate_total",&candidate);for((name,m),v)in phases{emit(p,sm,case,rep,&format!("verify_{name}"),&counted::Counts::from([(m,v)]));}calls+=1;}}}}assert_eq!(calls,24);eprintln!("calls=24 fixed_original_targets=12 certificates_pass=true reference_indexed_agreement=true mutations_rejected_each_verifier=84 source_basefield_generation_replay_exact=true phase_sums_exact=true exact_repeats=true candidate_cost=producer_minus_external_native_control_plus_certificate_verifier independent_verification=false");}
